<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {useQueryClient} from '@tanstack/vue-query';
import {Archive,LoaderCircle,RotateCcw,X} from 'lucide-vue-next';
import type {RepositoryLifecycleState} from '@oxen/shared';
import {post,repoBase,request} from '../api';
const emit=defineEmits<{restored:[]}>(),cache=useQueryClient(),items=ref<RepositoryLifecycleState[]>([]),loading=ref(false),error=ref(''),selected=ref<RepositoryLifecycleState>(),confirmation=ref(''),busy=ref(false);
async function load(){loading.value=true;error.value='';try{items.value=await request<RepositoryLifecycleState[]>('/repository-recycle-bin');}catch(cause){error.value=(cause as Error).message;}finally{loading.value=false;}}
async function restore(){const item=selected.value;if(!item||confirmation.value!==item.namespace+'/'+item.name)return;busy.value=true;error.value='';try{await post(repoBase(item.namespace,item.name)+'/lifecycle/restore',{confirmation:confirmation.value,removalId:item.removalId,revision:item.revision});selected.value=undefined;await cache.invalidateQueries({queryKey:['repos']});await load();emit('restored');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
onMounted(load);defineExpose({reload:load});
</script>
<template><details v-if="items.length||error" class="panel recycle-bin"><summary><Archive :size="16"/>本地回收站 <span>{{items.length}} 个项目</span></summary><p>已移除项目的 Oxen 版本与未完成工作保留。仅具备该项目管理权限的人员可查看和恢复。</p><p v-if="error" class="error-state" role="alert">{{error}}<button class="btn" @click="load">重试</button></p><div v-for="item in items" :key="item.namespace+'/'+item.name" class="recycle-item"><div><strong>{{item.displayName}}</strong><code>{{item.namespace}}/{{item.name}}</code><small>{{item.removedAt?new Date(item.removedAt).toLocaleString('zh-CN'):''}} 移除</small></div><button class="btn" @click="selected=item;confirmation=''">恢复项目<RotateCcw :size="14"/></button></div><p v-if="loading" role="status"><LoaderCircle class="spin" :size="16"/>读取回收记录…</p></details>
<div v-if="selected" class="modal-backdrop" @click.self="!busy&&(selected=undefined)"><form class="modal restore-dialog" role="dialog" aria-modal="true" aria-labelledby="restore-title" @submit.prevent="restore"><header><h3 id="restore-title">恢复项目</h3><button type="button" class="icon-button" :disabled="busy" aria-label="关闭恢复窗口" @click="selected=undefined"><X :size="18"/></button></header><p>恢复后，原有授权成员可继续访问项目及其全部版本。</p><label class="field">请输入 <code>{{selected.namespace}}/{{selected.name}}</code><input v-model="confirmation" autocomplete="off" aria-label="确认恢复的完整项目标识"/></label><p v-if="error" class="error-state" role="alert">{{error}}</p><footer><button type="button" class="btn" :disabled="busy" @click="selected=undefined">取消</button><button class="btn btn-primary" :disabled="busy||confirmation!==selected.namespace+'/'+selected.name"><LoaderCircle v-if="busy" class="spin" :size="15"/>恢复项目</button></footer></form></div></template>
<style scoped>.recycle-bin{margin-top:24px;padding:18px 22px}.recycle-bin summary{display:flex;align-items:center;gap:10px;cursor:pointer;font-size:13px}.recycle-bin summary span{margin-left:auto;color:var(--muted)}.recycle-bin p,.restore-dialog p{font-size:12px;color:var(--muted);line-height:1.9;margin:15px 0}.recycle-item{display:flex;justify-content:space-between;align-items:center;gap:15px;border-top:1px solid var(--line);padding:16px 0}.recycle-item code,.recycle-item small{display:block;color:var(--muted);font-size:11px;margin-top:6px;overflow-wrap:anywhere}.recycle-item strong{font-size:14px}.restore-dialog{padding:24px;max-width:500px}.restore-dialog header,.restore-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:15px}.restore-dialog footer{justify-content:flex-end;margin-top:20px}@media(max-width:600px){.recycle-item{align-items:flex-start;flex-wrap:wrap}.restore-dialog{margin:12px}}</style>
